Count the traffic flow:
function Xcount(a,b,time )
%XCOUNT Summary of this function goes here
%   Detailed explanation goes here
global Xsumsmall Xsumlarge Xsmallv Xlargev Xsumallcar;
global speedmaxl speedmaxs;

if (time<400||time>950)
    return
end
Xsumallcar=Xsumallcar+1;
if b==speedmaxl
    Xsumlarge=Xsumlarge+1;
    Xlargev=Xlargev+a;

elseif b==speedmaxs
    Xsumsmall=Xsumsmall+1;
    Xsmallv=Xsmallv+a;
end



end


